import React from 'react';
import { useFormik } from 'formik';
import * as Yup from 'yup';

const RegistrationForm = () => {
  const hobbiesOptions = [
    { label: 'Reading', value: 'reading' },
    { label: 'Gaming', value: 'gaming' },
    { label: 'Traveling', value: 'traveling' },
    { label: 'Cooking', value: 'cooking' },
  ];

  const formik = useFormik({
    initialValues: {
      firstName: '',
      lastName: '',
      email: '',
      phone: '',
      gender: '',
      userType: '',
      hobbies: [],
      profileImage: null,
      resume: null,
      agencyId: '',
    },
    validationSchema: Yup.object({
      firstName: Yup.string().required('First Name is required'),
      lastName: Yup.string().required('Last Name is required'),
      email: Yup.string().email('Invalid email').required('Email is required'),
      phone: Yup.string().required('Phone number is required'),
      gender: Yup.string().required('Gender is required'),
      userType: Yup.string().required('User type is required'),
      hobbies: Yup.array().min(1, 'At least one hobby is required'),
      // Add validation for file uploads if necessary
    }),
    onSubmit: async (values) => {
      const formData = new FormData();
      for (const key in values) {
        if (key === 'hobbies') {
          values.hobbies.forEach(hobby => formData.append('hobbies', hobby));
        } else {
          formData.append(key, values[key]);
        }
      }

      // Make the API call to register the user
      try {
        const response = await fetch('/api/users', {
          method: 'POST',
          body: formData,
        });
        const data = await response.json();
        console.log('User registered:', data);
      } catch (error) {
        console.error('Error registering user:', error);
      }
    },
  });

  return (
    <form onSubmit={formik.handleSubmit}>
      <div>
        <label>First Name:</label>
        <input
          type="text"
          name="firstName"
          onChange={formik.handleChange}
          value={formik.values.firstName}
        />
        {formik.errors.firstName && <div>{formik.errors.firstName}</div>}
      </div>
      <div>
        <label>Last Name:</label>
        <input
          type="text"
          name="lastName"
          onChange={formik.handleChange}
          value={formik.values.lastName}
        />
        {formik.errors.lastName && <div>{formik.errors.lastName}</div>}
      </div>
      <div>
        <label>Email:</label>
        <input
          type="email"
          name="email"
          onChange={formik.handleChange}
          value={formik.values.email}
        />
        {formik.errors.email && <div>{formik.errors.email}</div>}
      </div>
      <div>
        <label>Phone:</label>
        <input
          type="text"
          name="phone"
          onChange={formik.handleChange}
          value={formik.values.phone}
        />
        {formik.errors.phone && <div>{formik.errors.phone}</div>}
      </div>
      <div>
        <label>Gender:</label>
        <div>
          <label>
            <input
              type="radio"
              name="gender"
              value="male"
              onChange={formik.handleChange}
            />
            Male
          </label>
          <label>
            <input
              type="radio"
              name="gender"
              value="female"
              onChange={formik.handleChange}
            />
            Female
          </label>
        </div>
        {formik.errors.gender && <div>{formik.errors.gender}</div>}
      </div>
      <div>
        <label>User Type:</label>
        <select
          name="userType"
          onChange={formik.handleChange}
          value={formik.values.userType}
        >
          <option value="">Select</option>
          <option value="Job Seeker">Job Seeker</option>
          <option value="Agency">Agency</option>
        </select>
        {formik.errors.userType && <div>{formik.errors.userType}</div>}
      </div>
      <div>
        <label>Hobbies:</label>
        {hobbiesOptions.map((hobby) => (
          <label key={hobby.value}>
            <input
              type="checkbox"
              name="hobbies"
              value={hobby.value}
              onChange={formik.handleChange}
            />
            {hobby.label}
          </label>
        ))}
        {formik.errors.hobbies && <div>{formik.errors.hobbies}</div>}
      </div>
      <div>
        <label>Profile Image:</label>
        <input
          type="file"
          name="profileImage"
          onChange={(event) => {
            formik.setFieldValue("profileImage", event.currentTarget.files[0]);
          }}
        />
      </div>
      <div>
        <label>Resume:</label>
        <input
          type="file"
          name="resume"
          onChange={(event) => {
            formik.setFieldValue("resume", event.currentTarget.files[0]);
          }}
        />
      </div>
      <div>
        <label>Agency ID:</label>
        <input
          type="text"
          name="agencyId"
          onChange={formik.handleChange}
          value={formik.values.agencyId}
        />
      </div>
      <button type="submit">Register</button>
    </form>
  );
};

export default RegistrationForm;
